class Calculator:
    """
    This is a class for a calculator, capable of performing basic arithmetic calculations.
    """

    def __init__(self):
        self.operators = {
            '+': lambda x, y: x + y,
            '-': lambda x, y: x - y,
            '*': lambda x, y: x * y,
            '/': lambda x, y: x / y,
            '^': lambda x, y: x ** y
        }

    def precedence(self, operator):
        precedence_map = {'+': 1, '-': 1, '*': 2, '/': 2, '^': 3}
        return precedence_map.get(operator, 0)

    def apply_operator(self, operand_stack, operator_stack):
        if len(operand_stack) < 2 or not operator_stack:
            return operand_stack, operator_stack

        op = operator_stack.pop()
        right = operand_stack.pop()
        left = operand_stack.pop()

        try:
            result = self.operators[op](left, right)
            operand_stack.append(result)
        except ZeroDivisionError:
            return None, None
        return operand_stack, operator_stack

    def calculate(self, expression):
        # Tokenize: matches numbers (including decimals) or operators
        tokens = re.findall(r'\d+\.?\d*|[+\-*/^]', expression)
        operand_stack = []
        operator_stack = []

        for token in tokens:
            if token.replace('.', '', 1).isdigit():
                operand_stack.append(float(token))
            elif token in self.operators:
                while (operator_stack and 
                       self.precedence(operator_stack[-1]) >= self.precedence(token)):
                    operand_stack, operator_stack = self.apply_operator(operand_stack, operator_stack)
                    if operand_stack is None: return None
                operator_stack.append(token)

        while operator_stack:
            operand_stack, operator_stack = self.apply_operator(operand_stack, operator_stack)
            if operand_stack is None: return None

        return operand_stack[0] if operand_stack else None

