class CalendarUtil:
    def __init__(self):
        self.events = []

    def add_event(self, event):
        self.events.append(event)

    def remove_event(self, event):
        if event in self.events:
            self.events.remove(event)

    def get_events(self, date):
        # Comparing year, month, and day to ensure match
        return [e for e in self.events if e['date'].date() == date.date()]

    def is_available(self, start_time, end_time):
        for event in self.events:
            # Overlap logic: (StartA < EndB) and (EndA > StartB)
            if start_time < event['end_time'] and end_time > event['start_time']:
                return False
        return True

    def get_available_slots(self, date):
        # Filter events for the day and sort by start time
        day_events = sorted([e for e in self.events if e['date'].date() == date.date()], 
                            key=lambda x: x['start_time'])

        slots = []
        current_time = datetime(date.year, date.month, date.day, 0, 0)
        end_of_day = current_time + timedelta(days=1)

        for event in day_events:
            if event['start_time'] > current_time:
                slots.append((current_time, event['start_time']))
            current_time = max(current_time, event['end_time'])

        if current_time < end_of_day:
            slots.append((current_time, end_of_day))

        return slots

    def get_upcoming_events(self, num_events):
        # Sort all events by start_time and return the first n
        sorted_events = sorted(self.events, key=lambda x: x.get('start_time', x['date']))
        return sorted_events[:num_events]

