class CombinationCalculator:
    """
    This is a class that provides methods to calculate the number of combinations for a specific count, 
    calculate all possible combinations, and generate combinations with a specified number of elements.
    """

    def __init__(self, datas: List[str]):
        self.datas = datas

    @staticmethod
    def count(n: int, m: int) -> int:
        if m < 0 or m > n:
            return 0
        return math.comb(n, m)

    @staticmethod
    def count_all(n: int) -> int:
        limit = 2**63 - 1
        res = 2**n - 1
        return res if res <= limit else float("inf")

    def select(self, m: int) -> List[List[str]]:
        if m <= 0 or m > len(self.datas):
            return []
        result = []
        self._select(0, [None] * m, 0, result)
        return result

    def select_all(self) -> List[List[str]]:
        all_combinations = []
        for m in range(1, len(self.datas) + 1):
            all_combinations.extend(self.select(m))
        return all_combinations

    def _select(self, dataIndex: int, resultList: List[str], resultIndex: int, result: List[List[str]]):
        # Base case: combination is full
        if resultIndex == len(resultList):
            result.append(list(resultList))
            return

        # Recursive step: iterate through remaining data
        # Optimization: only iterate if enough elements remain to fill the rest of resultList
        for i in range(dataIndex, len(self.datas) - (len(resultList) - resultIndex - 1)):
            resultList[resultIndex] = self.datas[i]
            self._select(i + 1, resultList, resultIndex + 1, result)

