class DataStatistics4:
    """
    This is a class that performs advanced mathematical calculations and statistics.
    """

    @staticmethod
    def correlation_coefficient(data1, data2):
        n = len(data1)
        mu1, mu2 = sum(data1) / n, sum(data2) / n

        numerator = sum((data1[i] - mu1) * (data2[i] - mu2) for i in range(n))
        sum_sq_diff1 = sum((x - mu1) ** 2 for x in data1)
        sum_sq_diff2 = sum((x - mu2) ** 2 for x in data2)

        return numerator / math.sqrt(sum_sq_diff1 * sum_sq_diff2)

    @staticmethod
    def skewness(data):
        n = len(data)
        mu = sum(data) / n
        variance = sum((x - mu) ** 2 for x in data) / n

        m3 = sum((x - mu) ** 3 for x in data) / n
        return m3 / (variance ** 1.5)

    @staticmethod
    def kurtosis(data):
        n = len(data)
        mu = sum(data) / n
        variance = sum((x - mu) ** 2 for x in data) / n

        m4 = sum((x - mu) ** 4 for x in data) / n
        return (m4 / (variance ** 2)) - 3

    @staticmethod
    def pdf(data, mu, sigma):
        coeff = 1 / (sigma * math.sqrt(2 * math.pi))
        return [coeff * math.exp(-0.5 * ((x - mu) / sigma) ** 2) for x in data]

class DiscountStrategy:
    """
    This is a class that allows to use different discount strategy based on shopping credit or shopping cart in supermarket.
    """

    def __init__(self, customer, cart, promotion=None):
        self.customer = customer
        self.cart = cart
        self.promotion = promotion
        self._total = self.total()

    def total(self):
        """Calculate the total cost of items in the cart."""
        return sum(item['quantity'] * item['price'] for item in self.cart)

    def due(self):
        """Calculate the final amount to be paid after applying the discount."""
        discount = self.promotion(self) if self.promotion else 0.0
        return round(self._total - discount, 2)

    @staticmethod
    def FidelityPromo(order):
        """5% discount for customers with over 1000 points."""
        if order.customer.get('fidelity', 0) > 1000:
            return order._total * 0.05
        return 0.0

    @staticmethod
    def BulkItemPromo(order):
        """10% discount on items with quantity >= 20."""
        discount = 0.0
        for item in order.cart:
            if item['quantity'] >= 20:
                discount += (item['quantity'] * item['price']) * 0.1
        return discount

    @staticmethod
    def LargeOrderPromo(order):
        """7% discount if there are 10 or more distinct products."""
        if len(order.cart) >= 10:
            return order._total * 0.07
        return 0.0

