from docx import Document
from docx.shared import Pt
from docx.enum.text import WD_PARAGRAPH_ALIGNMENT

class DocFileHandler:
    """
    Handles Word documents for reading, writing, and modifying content.
    """

    def __init__(self, file_path):
        self.file_path = file_path
        if os.path.exists(file_path):
            self.doc = Document(file_path)
        else:
            self.doc = Document()

    def save(self):
        """Saves the current document state to the file path."""
        self.doc.save(self.file_path)

    def read_text(self):
        full_text = [para.text for para in self.doc.paragraphs]
        return '\n'.join(full_text)

    def write_text(self, content, font_size=12, alignment='left'):
        try:
            paragraph = self.doc.add_paragraph(content)
            paragraph.alignment = self._get_alignment_value(alignment)
            for run in paragraph.runs:
                run.font.size = Pt(font_size)
            self.save()
            return True
        except Exception:
            return False

    def add_heading(self, heading, level=1):
        try:
            self.doc.add_heading(heading, level=level)
            self.save()
            return True
        except Exception:
            return False

    def add_table(self, data):
        try:
            if not data: return False
            rows = len(data)
            cols = len(data[0])
            table = self.doc.add_table(rows=rows, cols=cols)
            table.style = 'Table Grid'
            for i, row_data in enumerate(data):
                for j, cell_data in enumerate(row_data):
                    table.cell(i, j).text = str(cell_data)
            self.save()
            return True
        except Exception:
            return False

    def _get_alignment_value(self, alignment):
        alignments = {
            'left': WD_PARAGRAPH_ALIGNMENT.LEFT,
            'center': WD_PARAGRAPH_ALIGNMENT.CENTER,
            'right': WD_PARAGRAPH_ALIGNMENT.RIGHT
        }
        return alignments.get(alignment.lower(), WD_PARAGRAPH_ALIGNMENT.LEFT)

