        moves = {'up': (-1, 0), 'down': (1, 0), 'left': (0, -1), 'right': (0, 1)}
        di, dj = moves[direction]
        ni, nj = i + di, j + dj

        if 0 <= ni < 3 and 0 <= nj < 3:
            new_state[i][j], new_state[ni][nj] = new_state[ni][nj], new_state[i][j]
            return new_state
        return None

    def get_possible_moves(self, state):
        i, j = self.find_blank(state)
        possible = []
        if i > 0: possible.append('up')
        if i < 2: possible.append('down')
        if j > 0: possible.append('left')
        if j < 2: possible.append('right')
        return possible

    def solve(self):
        # Queue stores (current_state, path_list)
        queue = deque([(self.initial_state, [])])
        visited = {str(self.initial_state)}

        while queue:
            current_state, path = queue.popleft()

            if current_state == self.goal_state:
                return path

            for direction in self.get_possible_moves(current_state):
                new_state = self.move(current_state, direction)
                if str(new_state) not in visited:
                    visited.add(str(new_state))
                    queue.append((new_state, path + [direction]))
        return None

from datetime import datetime

class EmailClient:
    """
    This is a class that serves as an email client, implementing functions such as checking emails, 
    determining whether there is sufficient space, and cleaning up space.
    """

    def __init__(self, addr, capacity) -> None:
        self.addr = addr
        self.capacity = capacity
        self.inbox = []

    def get_occupied_size(self):
        return sum(email['size'] for email in self.inbox)

    def is_full_with_one_more_email(self, size):
        return (self.get_occupied_size() + size) > self.capacity

    def send_to(self, recv, content, size):
        if recv.is_full_with_one_more_email(size):
            return False

        email = {
            'sender': self.addr,
            'receiver': recv.addr,
            'content': content,
            'size': size,
            'time': datetime.now().strftime('%Y-%m-%d %H:%M:%S'),
            'state': 'unread'
        }
        recv.inbox.append(email)
        return True

    def fetch(self):
        for email in self.inbox:
            if email['state'] == 'unread':
                email['state'] = 'read'
                return email
        return None

    def clear_inbox(self, size):
        while self.is_full_with_one_more_email(size) and self.inbox:
            self.inbox.pop(0)

class EncryptionUtils:
    """
    This is a class that provides methods for encryption, including the Caesar cipher, Vigenere cipher, and Rail Fence cipher.
    """

    def __init__(self, key):
        self.key = key

    def caesar_cipher(self, plaintext, shift):
        result = []
        for char in plaintext:
            if char.isalpha():
                start = ord('A') if char.isupper() else ord('a')
                # Shift and wrap around using modulo 26
                new_char = chr(start + (ord(char) - start + shift) % 26)
                result.append(new_char)
            else:
                result.append(char)
        return "".join(result)

    def vigenere_cipher(self, plaintext):
        result = []
        key = self.key.lower()
        key_index = 0

        for char in plaintext:
            if char.isalpha():
                shift = ord(key[key_index % len(key)]) - ord('a')
                start = ord('A') if char.isupper() else ord('a')
                new_char = chr(start + (ord(char) - start + shift) % 26)
                result.append(new_char)
                key_index += 1
            else:
                result.append(char)
        return "".join(result)

    def rail_fence_cipher(self, plain_text, rails):
        if rails == 1:
            return plain_text

        fence = [[] for _ in range(rails)]
        rail = 0
        direction = 1  # 1 for down, -1 for up

        for char in plain_text:
            fence[rail].append(char)
            if rails > 1:
                if rail == 0:
                    direction = 1
                elif rail == rails - 1:
                    direction = -1
                rail += direction

        return "".join(["".join(r) for r in fence])

