from collections import deque

class ExpressionCalculator:
    def __init__(self):
        self.postfix_stack = deque()
        # Priority map: +, -, *, /, %, (, )
        # Using ASCII/index mapping for simplicity
        self.ops = {'+': 1, '-': 1, '*': 2, '/': 2, '%': 2}

    @staticmethod
    def transform(expression):
        return expression.replace(" ", "")

    @staticmethod
    def is_operator(c):
        return c in {'+', '-', '*', '/', '(', ')', '%'}

    def compare(self, cur, peek):
        if peek == '(': return False
        return self.ops.get(cur, 0) <= self.ops.get(peek, 0)

    def prepare(self, expression):
        expression = self.transform(expression)
        output = []
        stack = []
        i = 0
        while i < len(expression):
            char = expression[i]
            if char.isdigit() or char == '.':
                num = ""
                while i < len(expression) and (expression[i].isdigit() or expression[i] == '.'):
                    num += expression[i]
                    i += 1
                output.append(num)
                continue
            elif char == '(':
                stack.append(char)
            elif char == ')':
                while stack and stack[-1] != '(':
                    output.append(stack.pop())
                stack.pop()
            elif self.is_operator(char):
                while stack and self.compare(char, stack[-1]):
                    output.append(stack.pop())
                stack.append(char)
            i += 1
        while stack:
            output.append(stack.pop())
        self.postfix_stack = deque(output)

    @staticmethod
    def _calculate(first_value, second_value, current_op):
        a, b = float(first_value), float(second_value)
        if current_op == '+': return a + b
        if current_op == '-': return a - b
        if current_op == '*': return a * b
        if current_op == '/': return a / b
        if current_op == '%': return a % b
        return 0.0

    def calculate(self, expression):
        self.prepare(expression)
        stack = []
        while self.postfix_stack:
            token = self.postfix_stack.popleft()
            if not self.is_operator(token):
                stack.append(token)
            else:
                val2 = stack.pop()
                val1 = stack.pop()
                res = self._calculate(val1, val2, token)
                stack.append(str(res))
        return float(stack[0])

