class FitnessTracker:
    """
    This is a class as fitness tracker that implements to calculate BMI (Body Mass Index) and calorie intake based on the user's height, weight, age, and sex.
    """

    def __init__(self, height, weight, age, sex) -> None:
        self.height = height * 100  # Converting to cm for BMR formula consistency
        self.weight = weight
        self.age = age
        self.sex = sex
        self.BMI_std = {
            "male": [20, 25],
            "female": [19, 24]
        }

    def get_BMI(self):
        # Height needs to be in meters for BMI calculation
        height_m = self.height / 100
        return self.weight / (height_m ** 2)

    def condition_judge(self):
        bmi = self.get_BMI()
        std = self.BMI_std.get(self.sex)
        if bmi > std[1]:
            return 1
        elif bmi < std[0]:
            return -1
        else:
            return 0

    def calculate_calorie_intake(self):
        # BMR formulas provided in prompt
        if self.sex == "male":
            bmr = 10 * self.weight + 6.25 * self.height - 5 * self.age + 5
        else:
            bmr = 10 * self.weight + 6.25 * self.height - 5 * self.age - 161

        condition = self.condition_judge()

        if condition == 1:  # too fat
            return bmr * 1.2
        elif condition == -1:  # too thin
            return bmr * 1.6
        else:  # normal
            return bmr * 1.4

class GomokuGame:
    """
    This class is an implementation of a Gomoku game, supporting for making moves, 
    checking for a winner, and checking if there are five consecutive symbols on the game board.
    """

    def __init__(self, board_size):
        self.board_size = board_size
        self.board = [[' ' for _ in range(board_size)] for _ in range(board_size)]
        self.current_player = 'X'

    def make_move(self, row, col):
        if 0 <= row < self.board_size and 0 <= col < self.board_size and self.board[row][col] == ' ':
            self.board[row][col] = self.current_player
            self.current_player = 'O' if self.current_player == 'X' else 'X'
            return True
        return False

    def check_winner(self):
        directions = [(0, 1), (1, 0), (1, 1), (1, -1)]
        for r in range(self.board_size):
            for c in range(self.board_size):
                if self.board[r][c] != ' ':
                    for d in directions:
                        if self._check_five_in_a_row(r, c, d):
                            return self.board[r][c]
        return None

    def _check_five_in_a_row(self, row, col, direction):
        dx, dy = direction
        symbol = self.board[row][col]

        for i in range(1, 5):
            r, c = row + i * dx, col + i * dy
            if not (0 <= r < self.board_size and 0 <= c < self.board_size and self.board[r][c] == symbol):
                return False
        return True

class Hotel:
    def __init__(self, name, rooms):
        self.name = name
        self.available_rooms = rooms
        self.booked_rooms = {}

    def book_room(self, room_type, room_number, name):
        if room_type not in self.available_rooms:
            return False

        available = self.available_rooms[room_type]

        if room_number <= available:
            self.available_rooms[room_type] -= room_number
            if room_type not in self.booked_rooms:
                self.booked_rooms[room_type] = {}

            self.booked_rooms[room_type][name] = self.booked_rooms[room_type].get(name, 0) + room_number
            return 'Success!'
        elif available > 0:
            return available
        else:
            return False

    def check_in(self, room_type, room_number, name):
        if room_type not in self.booked_rooms or name not in self.booked_rooms[room_type]:
            return False

        if room_number > self.booked_rooms[room_type][name]:
            return False

        self.booked_rooms[room_type][name] -= room_number
        if self.booked_rooms[room_type][name] == 0:
            del self.booked_rooms[room_type][name]

    def check_out(self, room_type, room_number):
        if room_type in self.available_rooms:
            self.available_rooms[room_type] += room_number
        else:
            self.available_rooms[room_type] = room_number

    def get_available_rooms(self, room_type):
        return self.available_rooms.get(room_type, 0)

