class IPAddress:
    """
    This is a class to process IP Address, including validating, getting the octets and obtaining the binary representation of a valid IP address.
    """

    def __init__(self, ip_address):
        """
        Initialize the IP address to the specified address
        :param ip_address:string
        """
        self.ip_address = ip_address

    def is_valid(self):
        """
        Judge whether the IP address is valid.
        :return: bool
        """
        parts = self.ip_address.split('.')
        if len(parts) != 4:
            return False

        for part in parts:
            # Check if part is numeric and within range 0-255
            if not part.isdigit():
                return False
            num = int(part)
            if num < 0 or num > 255:
                return False
            # Optional: Check for leading zeros (e.g., "01" is often considered invalid)
            if len(part) > 1 and part.startswith('0'):
                return False
        return True

    def get_octets(self):
        """
        If the IP address is valid, the list of four decimal numbers is returned; 
        otherwise, an empty list is returned.
        :return: list
        """
        if self.is_valid():
            return self.ip_address.split('.')
        return []

    def get_binary(self):
        """
        If the IP address is valid, return the binary form of the IP address; 
        otherwise, return ''.
        :return: string
        """
        octets = self.get_octets()
        if not octets:
            return ''

        binary_parts = []
        for octet in octets:
            # Convert to int, then to binary string, remove '0b' prefix, pad to 8 chars
            bin_val = bin(int(octet))[2:].zfill(8)
            binary_parts.append(bin_val)

        return ".".join(binary_parts)

