import os

class JSONProcessor:
    """
    This is a class to process JSON file, including reading and writing JSON files, 
    as well as processing JSON data by removing a specified key from the JSON object.
    """

    def read_json(self, file_path):
        if not os.path.exists(file_path):
            return 0
        try:
            with open(file_path, 'r') as f:
                return json.load(f)
        except (json.JSONDecodeError, IOError):
            return -1

    def write_json(self, data, file_path):
        try:
            with open(file_path, 'w') as f:
                json.dump(data, f, indent=4)
            return 1
        except (TypeError, IOError):
            return -1

    def process_json(self, file_path, remove_key):
        # Read the current data
        data = self.read_json(file_path)

        # Handle errors or missing file from read_json
        if data == 0 or data == -1:
            return 0 if data == 0 else -1

        # Check if key exists
        if remove_key not in data:
            return 0

        # Remove the key
        del data[remove_key]

        # Write back to file
        return self.write_json(data, file_path)

import random

class MahjongConnect:
    def __init__(self, BOARD_SIZE, ICONS):
        self.BOARD_SIZE = BOARD_SIZE
        self.ICONS = ICONS
        self.board = self.create_board()

    def create_board(self):
        rows, cols = self.BOARD_SIZE
        total_cells = rows * cols
        # Create pairs of icons to fill the board
        flat_list = (self.ICONS * (total_cells // len(self.ICONS) + 1))[:total_cells]
        random.shuffle(flat_list)
        return [flat_list[i * cols:(i + 1) * cols] for i in range(rows)]

    def is_valid_move(self, pos1, pos2):
        r1, c1 = pos1
        r2, c2 = pos2
        rows, cols = self.BOARD_SIZE

        # Bounds check
        if not (0 <= r1 < rows and 0 <= c1 < cols and 0 <= r2 < rows and 0 <= c2 < cols):
            return False
        # Same position check
        if pos1 == pos2:
            return False
        # Empty cell check
        if self.board[r1][c1] == ' ' or self.board[r2][c2] == ' ':
            return False
        # Icon match check
        if self.board[r1][c1] != self.board[r2][c2]:
            return False

        return self.has_path(pos1, pos2)

    def has_path(self, pos1, pos2):
        # BFS to find path with at most 2 turns
        rows, cols = self.BOARD_SIZE
        queue = [(pos1[0], pos1[1], -1, -1, 0)] # r, c, last_dr, last_dc, turns
        visited = {} # (r, c) -> min_turns

        while queue:
            r, c, last_dr, last_dc, turns = queue.pop(0)

            if (r, c) == pos2:
                return True

            for dr, dc in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nr, nc = r + dr, c + dc
                new_turns = turns + (1 if (last_dr != -1 and (dr != last_dr or dc != last_dc)) else 0)

                if 0 <= nr < rows and 0 <= nc < cols and new_turns <= 2:
                    if self.board[nr][nc] == ' ' or (nr, nc) == pos2:
                        if visited.get((nr, nc), 3) > new_turns:
                            visited[(nr, nc)] = new_turns
                            queue.append((nr, nc, dr, dc, new_turns))
        return False

    def remove_icons(self, pos1, pos2):
        self.board[pos1[0]][pos1[1]] = ' '
        self.board[pos2[0]][pos2[1]] = ' '

    def is_game_over(self):
        for row in self.board:
            for cell in row:
                if cell != ' ':
                    return False
        return True

class MetricsCalculator:
    """
    The class calculates precision, recall, F1 score, and accuracy based on predicted and true labels.
    """

    def __init__(self):
        self.true_positives = 0
        self.false_positives = 0
        self.false_negatives = 0
        self.true_negatives = 0

    def update(self, predicted_labels, true_labels):
        for p, t in zip(predicted_labels, true_labels):
            if p == 1 and t == 1:
                self.true_positives += 1
            elif p == 1 and t == 0:
                self.false_positives += 1
            elif p == 0 and t == 1:
                self.false_negatives += 1
            elif p == 0 and t == 0:
                self.true_negatives += 1

    def precision(self, predicted_labels, true_labels):
        # Reset and update to ensure calculation is based on current input
        self.__init__()
        self.update(predicted_labels, true_labels)

        denominator = self.true_positives + self.false_positives
        return self.true_positives / denominator if denominator != 0 else 0.0

    def recall(self, predicted_labels, true_labels):
        self.__init__()
        self.update(predicted_labels, true_labels)

        denominator = self.true_positives + self.false_negatives
        return self.true_positives / denominator if denominator != 0 else 0.0

    def f1_score(self, predicted_labels, true_labels):
        p = self.precision(predicted_labels, true_labels)
        r = self.recall(predicted_labels, true_labels)

        denominator = p + r
        return 2 * (p * r) / denominator if denominator != 0 else 0.0

    def accuracy(self, predicted_labels, true_labels):
        self.__init__()
        self.update(predicted_labels, true_labels)

        total = self.true_positives + self.false_positives + self.false_negatives + self.true_negatives
        return (self.true_positives + self.true_negatives) / total if total != 0 else 0.0

import numpy as np

class MetricsCalculator2:
    """
    The class provides to calculate Mean Reciprocal Rank (MRR) and Mean Average Precision (MAP).
    """

    def __init__(self):
        pass

    @staticmethod
    def mrr(data):
        # Normalize input to a list of tuples
        if isinstance(data, tuple):
            data = [data]

        reciprocal_ranks = []
        for results, _ in data:
            try:
                # Find index of first 1 (rank is index + 1)
                rank = results.index(1) + 1
                reciprocal_ranks.append(1.0 / rank)
            except ValueError:
                # No 1 found
                reciprocal_ranks.append(0.0)

        return np.mean(reciprocal_ranks), reciprocal_ranks

    @staticmethod
    def map(data):
        # Normalize input to a list of tuples
        if isinstance(data, tuple):
            data = [data]

        ap_list = []
        for results, ground_truth_num in data:
            if ground_truth_num == 0:
                ap_list.append(0.0)
                continue

            hits = 0
            sum_precision = 0.0
            for i, val in enumerate(results):
                if val == 1:
                    hits += 1
                    precision_at_k = hits / (i + 1)
                    sum_precision += precision_at_k

            # AP = sum of precision at each hit / total ground truth
            ap = sum_precision / ground_truth_num
            ap_list.append(ap)

        return np.mean(ap_list), ap_list

