class MinesweeperGame:
    """
    This is a class that implements mine sweeping games including minesweeping and winning judgment.
    """

    def __init__(self, n, k) -> None:
        """
        Initializes the MinesweeperGame class with the size of the board and the number of mines.
        """
        self.n = n
        self.k = k
        self.minesweeper_map = self.generate_mine_sweeper_map()
        self.player_map = self.generate_playerMap()
        self.score = 0

    def generate_mine_sweeper_map(self):
        """
        1. Create an n x n grid filled with 0s.
        2. Randomly place k mines ('X').
        3. For each non-mine cell, count adjacent mines and update the cell with that number.
        """
        grid = [[0 for _ in range(self.n)] for _ in range(self.n)]
        mines = set()
        while len(mines) < self.k:
            mines.add((random.randint(0, self.n - 1), random.randint(0, self.n - 1)))

        for r, c in mines:
            grid[r][c] = 'X'

        for r in range(self.n):
            for c in range(self.n):
                if grid[r][c] == 'X':
                    continue
                count = 0
                for dr in [-1, 0, 1]:
                    for dc in [-1, 0, 1]:
                        nr, nc = r + dr, c + dc
                        if 0 <= nr < self.n and 0 <= nc < self.n and grid[nr][nc] == 'X':
                            count += 1
                grid[r][c] = count
        return grid

    def generate_playerMap(self):
        """
        Creates an n x n grid filled with '-' representing unknown positions.
        """
        return [['-' for _ in range(self.n)] for _ in range(self.n)]

    def check_won(self, map):
        """
        The player wins if all non-mine cells are revealed.
        Count revealed cells; if (n*n - k) cells are revealed, return True.
        """
        revealed_count = 0
        for r in range(self.n):
            for c in range(self.n):
                if map[r][c] != '-':
                    revealed_count += 1
        return revealed_count == (self.n * self.n - self.k)

    def sweep(self, x, y):
        """
        1. If the position is a mine, the game ends (or handle as loss).
        2. If not a mine, update player_map with the value from minesweeper_map.
        3. Check if the player has won.
        """
        if self.minesweeper_map[x][y] == 'X':
            return "Game Over: Hit a mine!"

        self.player_map[x][y] = self.minesweeper_map[x][y]

        if self.check_won(self.player_map):
            return True
        return self.player_map

from datetime import datetime
import numpy as np

class MovieBookingSystem:
    def __init__(self):
        self.movies = []

    def add_movie(self, name, price, start_time, end_time, n):
        # Parse time strings into datetime objects
        fmt = '%H:%M'
        start = datetime.strptime(start_time, fmt)
        end = datetime.strptime(end_time, fmt)

        # Create seat grid
        seats = np.zeros((n, n))

        movie = {
            'name': name,
            'price': price,
            'start_time': start,
            'end_time': end,
            'seats': seats
        }
        self.movies.append(movie)

    def book_ticket(self, name, seats_to_book):
        movie = next((m for m in self.movies if m['name'] == name), None)

        if not movie:
            return "Movie not found."

        # Check if all requested seats are available
        for r, c in seats_to_book:
            # Check bounds
            if r < 0 or r >= movie['seats'].shape[0] or c < 0 or c >= movie['seats'].shape[1]:
                return "Booking failed."
            # Check if already booked
            if movie['seats'][r, c] == 1:
                return "Booking failed."

        # Perform booking
        for r, c in seats_to_book:
            movie['seats'][r, c] = 1

        return "Booking success."

    def available_movies(self, start_time, end_time):
        fmt = '%H:%M'
        query_start = datetime.strptime(start_time, fmt)
        query_end = datetime.strptime(end_time, fmt)

        available = []
        for movie in self.movies:
            # Check if movie time is within the range
            if movie['start_time'] >= query_start and movie['end_time'] <= query_end:
                available.append(movie['name'])

        return available

class NumberConverter:
    """
    The class allows to convert decimal to binary, octal and hexadecimal respectively and contrarily
    """

    @staticmethod
    def decimal_to_binary(decimal_num):
        """
        Convert a number from decimal format to binary format.
        """
        return bin(decimal_num)[2:]

    @staticmethod
    def binary_to_decimal(binary_num):
        """
        Convert a number from binary format to decimal format.
        """
        return int(binary_num, 2)

    @staticmethod
    def decimal_to_octal(decimal_num):
        """
        Convert a number from decimal format to octal format.
        """
        return oct(decimal_num)[2:]

    @staticmethod
    def octal_to_decimal(octal_num):
        """
        Convert a number from octal format to decimal format.
        """
        return int(octal_num, 8)

    @staticmethod
    def decimal_to_hex(decimal_num):
        """
        Convert a number from decimal format to hex format.
        """
        return hex(decimal_num)[2:]

    @staticmethod
    def hex_to_decimal(hex_num):
        """
        Convert a number from hex format to decimal format.
        """
        return int(hex_num, 16)

class NumberWordFormatter:
    def __init__(self):
        self.NUMBER = ["", "ONE", "TWO", "THREE", "FOUR", "FIVE", "SIX", "SEVEN", "EIGHT", "NINE"]
        self.NUMBER_TEEN = ["TEN", "ELEVEN", "TWELVE", "THIRTEEN", "FOURTEEN", "FIFTEEN", "SIXTEEN", "SEVENTEEN",
                            "EIGHTEEN", "NINETEEN"]
        self.NUMBER_TEN = ["", "", "TWENTY", "THIRTY", "FORTY", "FIFTY", "SIXTY", "SEVENTY", "EIGHTY", "NINETY"]
        self.NUMBER_MORE = ["", "THOUSAND", "MILLION", "BILLION", "TRILLION"]

    def trans_two(self, s):
        n = int(s)
        if n < 10:
            return self.NUMBER[n]
        elif n < 20:
            return self.NUMBER_TEEN[n - 10]
        else:
            tens = self.NUMBER_TEN[n // 10]
            ones = self.NUMBER[n % 10]
            return f"{tens} {ones}".strip()

    def trans_three(self, s):
        n = int(s)
        if n == 0: return ""
        if n < 100: return self.trans_two(str(n))

        hundreds = self.NUMBER[n // 100] + " HUNDRED"
        remainder = self.trans_two(str(n % 100))
        return f"{hundreds} AND {remainder}".strip() if remainder else hundreds

    def parse_more(self, i):
        return self.NUMBER_MORE[i] if i < len(self.NUMBER_MORE) else ""

    def format_string(self, x):
        # Split into groups of 3
        groups = []
        s = x.zfill((len(x) + 2) // 3 * 3)
        for i in range(len(s), 0, -3):
            groups.append(s[max(0, i-3):i])

        parts = []
        for i, group in enumerate(groups):
            val = self.trans_three(group)
            if val:
                unit = self.parse_more(i)
                parts.append(f"{val} {unit}".strip())

        return " ".join(reversed(parts)) + " ONLY"

    def format(self, x):
        # Handle float/int conversion
        return self.format_string(str(int(x)))

